mapper.select:
SELECT COUNT(DISTINCT w.id) FROM repair_worker w
JOIN repair_worker_fault_type wf ON wf.worker_id=w.id AND wf.status=1 AND wf.fault_type_id=#{faultTypeId}
WHERE w.deleted=0

SELECT COUNT(DISTINCT w.id) FROM repair_worker w
JOIN repair_worker_fault_type wf ON wf.worker_id=w.id AND wf.status=1 AND wf.fault_type_id=#{faultTypeId}
JOIN repair_worker_area_scope s ON s.worker_id=w.id AND s.status=1 AND s.campus_id=#{campusId}
  AND (s.area_id IS NULL OR s.area_id=#{areaId}) AND (s.building_id IS NULL OR s.building_id=#{buildingId})
WHERE w.deleted=0
